(function(){
  function enterGuestFallback(){
    try{
      var guest={uid:'guest_local',email:'guest@champword.local',displayName:'Guest'};
      var guestProfile={displayName:'Guest',coins:12480,gems:320,level:12,xp:680,wins:0,games:0};
      localStorage.setItem('wordunoLocalUser', JSON.stringify(guest));
      localStorage.setItem('wordunoLocalProfile_guest_local', JSON.stringify(guestProfile));
      localStorage.setItem('champwordLocalUser', JSON.stringify(guest));
      localStorage.setItem('champwordLocalProfile_guest_local', JSON.stringify(guestProfile));
    }catch(e){}
    document.body.classList.remove('auth-open');
    document.body.classList.add('app-open');
    document.querySelectorAll('.screen').forEach(function(x){x.classList.add('hidden')});
    var dash=document.getElementById('finalDashboard');
    if(dash) dash.classList.remove('hidden');
    var name=document.getElementById('homeName'); if(name) name.textContent='Guest';
    var q=document.getElementById('homeQuickPlay'); if(q) q.focus();
  }
  window.enterGuestFallback=enterGuestFallback;

  function openQuick(){
    var m=document.getElementById('homeQuickModal');
    if(m){m.classList.remove('hidden');m.setAttribute('aria-hidden','false');}
  }
  function closeQuick(){
    var m=document.getElementById('homeQuickModal');
    if(m){m.classList.add('hidden');m.setAttribute('aria-hidden','true');}
  }
  document.addEventListener('DOMContentLoaded',function(){
    var g=document.getElementById('guestBtn');
    if(g) g.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();if(typeof window.enterGuest==='function') window.enterGuest(); else enterGuestFallback();},true);

    document.addEventListener('click',function(e){
      var id=e.target && e.target.id;
      if(id==='homeQuickPlay' || id==='homePlayFun') openQuick();
      if(id==='hqClose') closeQuick();
      if(id==='hqStart'){
        closeQuick();
        if(typeof window.startGame==='function') window.startGame();
        else {
          var game=document.getElementById('game'); if(game){document.querySelectorAll('.screen').forEach(function(x){x.classList.add('hidden')});game.classList.remove('hidden');}
        }
      }
      if(id==='homeSettings'||id==='bottomSettings') {
        var s=document.getElementById('settings'); if(s){document.querySelectorAll('.screen').forEach(function(x){x.classList.add('hidden')});s.classList.remove('hidden');}
      }
      if(id==='homeFriends'||id==='bottomFriends'){
        var s=document.getElementById('social'); if(s){document.querySelectorAll('.screen').forEach(function(x){x.classList.add('hidden')});s.classList.remove('hidden');}
      }
      if(id==='homeRoom'){
        var s=document.getElementById('party'); if(s){document.querySelectorAll('.screen').forEach(function(x){x.classList.add('hidden')});s.classList.remove('hidden');}
      }
      if(id==='bottomEvents'||id==='homeRewards'){
        var s=document.getElementById('progress'); if(s){document.querySelectorAll('.screen').forEach(function(x){x.classList.add('hidden')});s.classList.remove('hidden');}
      }
      if(id==='bottomStore'){
        var s=document.getElementById('shop'); if(s){document.querySelectorAll('.screen').forEach(function(x){x.classList.add('hidden')});s.classList.remove('hidden');}
      }
    });
  });
})();

(function(){
  // Emergency-independent navigation bridge: Profile must open even if the
  // Firebase/game module is delayed or fails to initialize.
  window.__openChampProfile = function(){
    if(typeof window.openChampProfile==='function'){window.openChampProfile();return;}
    document.querySelectorAll('.screen').forEach(function(x){x.classList.add('hidden');});
    var gate=document.getElementById('orientationGate'); if(gate) gate.style.display='none';
    var profile=document.getElementById('profile');
    if(!profile) return;
    profile.classList.remove('hidden');
    document.body.classList.remove('auth-open','app-open');
    document.body.classList.add('profile-open');
    var basic=document.getElementById('profileBasicView');
    var detail=document.getElementById('profileDetailView');
    var studio=document.getElementById('profileStudioView');
    if(basic) basic.classList.remove('hidden');
    if(detail) detail.classList.add('hidden');
    if(studio) studio.classList.add('hidden');
    document.querySelectorAll('.profile-side-link').forEach(function(x){x.classList.toggle('active',x.getAttribute('data-profile-view')==='basic');});
    document.querySelectorAll('.profile-tab').forEach(function(x){x.classList.toggle('active',x.getAttribute('data-profile-tab')==='basic');});
  };
  function fire(id){
    if(id==='profileBtn'){window.__openChampProfile();return;}
    var el=document.getElementById(id); if(el)el.click();
  }
  function intercept(e){
    var b=e.target && e.target.closest ? e.target.closest('[data-v37-target]') : null;
    if(!b)return;
    var id=b.getAttribute('data-v37-target');
    if(id==='profileBtn'){e.preventDefault();e.stopPropagation();window.__openChampProfile();}
    else if(e.type==='click'){e.preventDefault();e.stopPropagation();fire(id);}
  }
  document.addEventListener('pointerdown',intercept,true);
  document.addEventListener('touchend',intercept,true);
  document.addEventListener('click',intercept,true);
})();

