function renderClassicTablePlayers(players){
 const game=document.getElementById('game');if(!game)return;
 installClassicTablePlayerStyle();
 let root=game.querySelector('.classic-table-players');
 if(!root){root=document.createElement('div');root.className='classic-table-players';game.appendChild(root);}
 const positions=['bottom','left','top','right'];
 root.innerHTML=positions.map((pos,i)=>{const p=players[i];if(!p)return '';const av=p.avatar||defaultAvatar;return `<div class="classic-table-player ${pos}" data-player-id="${esc(p.id)}"><div class="ctp-chair"></div><div class="ctp-avatar">${avatarMarkup('table',av)}</div><div class="ctp-name">${esc(p.name||'Player')}</div></div>`}).join('');
}
async function hydrateClassicPlayerAvatars(players){
 if(!db||!players?.length)return;
 const missing=players.filter(p=>p?.id && !String(p.id).startsWith('bot_') && !classicAvatarCache[p.id]);
 if(!missing.length)return;
 await Promise.all(missing.map(async p=>{
   if(p.id===user?.uid){classicAvatarCache[p.id]=avatarData();return;}
   try{const snap=await getDoc(doc(db,'users',p.id));const d=snap.exists()?snap.data():null;classicAvatarCache[p.id]=d?.avatar||defaultAvatar;}catch(e){classicAvatarCache[p.id]=defaultAvatar;}
 }));
 players.forEach(p=>{if(p?.id&&classicAvatarCache[p.id])p.avatar=classicAvatarCache[p.id];});
}

function audio(){if(!soundOn)return null;audioCtx??=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx}
function tone(freq,duration=.12,type='sine',gain=.045,delay=0){const c=audio();if(!c)return;const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(0,c.currentTime+delay);g.gain.linearRampToValueAtTime(gain,c.currentTime+delay+.015);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+delay+duration);o.connect(g).connect(c.destination);o.start(c.currentTime+delay);o.stop(c.currentTime+delay+duration+.02)}
function playSound(type){if(!soundOn)return;if(type==='plus4_challenge'||type==='plus4_accept'){tone(type==='plus4_challenge'?180:280,.15,'triangle',.045);tone(type==='plus4_challenge'?120:420,.2,'triangle',.04,.1)}else if(type==='uno_challenge'){tone(150,.16,'sawtooth',.05);tone(100,.2,'sawtooth',.04,.1)}else if(type==='card_play'){tone(420,.08,'triangle',.05);tone(620,.12,'triangle',.035,.07)}else if(type==='draw'){tone(180,.12,'sine',.035)}else if(type==='uno'){tone(660,.12,'square',.05);tone(880,.2,'square',.045,.12)}else if(type==='skip'){tone(330,.1,'sawtooth',.04);tone(220,.16,'sawtooth',.035,.08)}else if(type==='reverse'){tone(260,.1,'triangle',.04);tone(390,.1,'triangle',.04,.08);tone(260,.16,'triangle',.035,.16)}else if(type==='wild'){tone(520,.09,'triangle',.04);tone(780,.09,'triangle',.04,.09);tone(1040,.18,'triangle',.035,.18)}else if(type==='plus4'){tone(130,.18,'sawtooth',.045);tone(90,.24,'sawtooth',.04,.12)}else if(type==='win'){[523,659,784,1047].forEach((f,i)=>tone(f,.2,'triangle',.05,i*.11))}}
function banner(text){const el=$('eventBanner');if(!el)return;el.textContent=text;el.classList.remove('show');void el.offsetWidth;el.classList.add('show')}
function confetti(){const layer=$('confettiLayer');if(!layer)return;for(let i=0;i<34;i++){const x=document.createElement('i');x.className='confetti';x.style.setProperty('--x',Math.random());x.style.transform=`rotate(${Math.random()*180}deg)`;x.style.left=(35+Math.random()*30)+'%';x.style.animationDelay=(Math.random()*.15)+'s';layer.appendChild(x);setTimeout(()=>x.remove(),1800)}}
function handleGameEvent(s){const ev=s.lastEvent;if(!ev||ev.id===lastEventId)return;lastEventId=ev.id;const type=ev.type;if(type==='card_play'){const names={skip:'SKIP!',reverse:'REVERSE!',plus2:'+2',plus4:'WILD +4',wild:'WILD!',word:ev.word||'PLAY'};banner(names[ev.cardType]||ev.word||'PLAY');playSound(ev.cardType==='skip'?'skip':ev.cardType==='reverse'?'reverse':ev.cardType==='plus4'?'plus4':ev.cardType==='wild'?'wild':'card_play');const f=$('tableFlash');f.classList.remove('active');void f.offsetWidth;f.classList.add('active');if(s.over) {playSound('win');confetti()}}else if(type==='draw'){banner('DRAW');playSound('draw')}else if(type==='uno'){banner('UNO!');playSound('uno')}}

function show(id){if(id==='home')id='finalDashboard';document.querySelectorAll('.screen').forEach(x=>x.classList.add('hidden'));const el=$(id);if(el)el.classList.remove('hidden');document.body.classList.toggle('auth-open',id==='auth');document.body.classList.toggle('app-open',id==='finalDashboard');document.body.classList.toggle('profile-open',id==='profile');if(id==='finalDashboard'){document.querySelector('.final-app')?.classList.remove('detail-mode');renderFinalDashboard()}if(id==='profile'){renderProfileDashboard()}}
function esc(s){return String(s??'').replace(/[&<>'"]/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[x]))}
function msg(t){$('gameMessage').textContent=t}
function startPresence(){stopPresence();const ping=async()=>{if(!user||!db)return;try{await setDoc(doc(db,'users',user.uid),{online:true,lastSeen:new Date(),updatedAt:new Date()},{merge:true})}catch(e){}};ping();presenceTimer=setInterval(ping,30000)}
function stopPresence(){if(presenceTimer)clearInterval(presenceTimer);presenceTimer=null}
window.addEventListener('beforeunload',()=>{if(user&&db) setDoc(doc(db,'users',user.uid),{online:false,lastSeen:new Date(),updatedAt:new Date()},{merge:true}).catch(()=>{})});
async function boot(){
  if(demo){
    const saved=localStorage.getItem('wordunoLocalUser');
    if(saved){
      try{user=JSON.parse(saved); await loadProfile(); updateHome(); show('finalDashboard');}
      catch(e){localStorage.removeItem('wordunoLocalUser'); show('auth')}
    }else show('auth');
    return;
  }
  try{app=initializeApp(firebaseConfig);auth=getAuth(app);db=getFirestore(app);functions=getFunctions(app)}catch(e){console.warn('Firebase initialization failed; continuing in local mode.',e);show('auth');return;}
  onAuthStateChanged(auth,async u=>{user=u;if(u){await loadProfile();updateHome();startSocialListeners();startPresence();if(!(await restoreRoom())){show('finalDashboard');localStartGame()}}else{stopSocialListeners();stopPresence();show('auth')}})
}
async function loadProfile(){
  if(demo){
    const key='wordunoLocalProfile_'+user.uid;const saved=localStorage.getItem(key);
    if(saved){profile={...profile,...JSON.parse(saved)};}else{profile.displayName=user.displayName||'Player';persistLocalProfile()}
    return;
  }
  const s=await getDoc(doc(db,'users',user.uid));if(s.exists())profile={...profile,...s.data(),achievements:{...profile.achievements,...(s.data().achievements||{})},inventory:{...profile.inventory,...(s.data().inventory||{})}};else{profile.displayName=user.displayName||'Player';await setDoc(doc(db,'users',user.uid),{...profile,displayName:profile.displayName,updatedAt:new Date()})}
}
function persistLocalProfile(){if(!user)return;localStorage.setItem('wordunoLocalProfile_'+user.uid,JSON.stringify(profile))}
function enterGuest(){
  user={uid:'guest_'+Date.now(),email:'guest@worduno.local',displayName:'Guest'};
  profile={...profile,displayName:'Guest',coins:12480,gems:320,level:12,xp:680};
  localStorage.setItem('wordunoLocalUser',JSON.stringify(user));
  persistLocalProfile();
  $('authMessage').textContent='Guest mode started. Welcome to Word UNO!';
  updateHome();
  show('finalDashboard');
  localStartGame();
}
window.enterGuest=enterGuest;
async function authAction(type){
  const email=$('emailInput').value.trim().toLowerCase(),password=$('passwordInput').value,name=$('nameInput').value.trim()||'Player';
  if(!email||!email.includes('@')||password.length<6){$('authMessage').textContent='Enter a valid email and a password of at least 6 characters.';return}
  if(demo){
    const users=JSON.parse(localStorage.getItem('wordunoLocalAccounts')||'{}');
    if(type==='signup'){
      if(users[email]){$('authMessage').textContent='An account with this email already exists. Log in instead.';return}
      const uid='local_'+btoa(email).replace(/[^a-z0-9]/gi,'').slice(0,18)+'_'+Date.now();
      users[email]={uid,email,password,displayName:name};localStorage.setItem('wordunoLocalAccounts',JSON.stringify(users));
      user={uid,email,displayName:name};profile={...profile,displayName:name,coins:12480,gems:320,level:12,xp:680};persistLocalProfile();localStorage.setItem('wordunoLocalUser',JSON.stringify(user));
      $('authMessage').textContent='Account created.';updateHome();show('finalDashboard');return;
    }
    const rec=users[email];
    if(!rec||rec.password!==password){$('authMessage').textContent='Email or password is incorrect.';return}
    user={uid:rec.uid,email:rec.email,displayName:rec.displayName};localStorage.setItem('wordunoLocalUser',JSON.stringify(user));await loadProfile();$('authMessage').textContent='';updateHome();show('finalDashboard');return;
  }
  try{let cred;if(type==='signup'){cred=await createUserWithEmailAndPassword(auth,email,password);await updateProfile(cred.user,{displayName:name});await call('ensureProfile')({displayName:name});}else cred=await signInWithEmailAndPassword(auth,email,password);$('authMessage').textContent=''}catch(e){$('authMessage').textContent=e.message.replace('Firebase: ','')}
}
function xpForLevel(l){return Math.max(100,(Number(l)||1)*100)}
function updateHome(){
 const set=(id,v)=>{const el=$(id);if(el)el.textContent=v};
 set('topName',profile.displayName);set('welcome',profile.displayName);set('coins',profile.coins??0);set('topCoins',profile.coins??0);set('wins',profile.wins??0);set('games',profile.games??0);set('streak',profile.streak??0);set('level',profile.level??1);set('dashLevel',profile.level??1);
 const need=xpForLevel(profile.level||1),xp=Number(profile.xp||0);set('xpText',`${xp} / ${need} XP`);const bar=$('xpBar');if(bar)bar.style.width=Math.min(100,xp/need*100)+'%';
 const today=new Date().toISOString().slice(0,10);const last=profile.lastDailyClaim?.toDate?profile.lastDailyClaim.toDate():profile.lastDailyClaim?new Date(profile.lastDailyClaim):null;const claimed=!!last&&!Number.isNaN(last.getTime())&&last.toISOString().slice(0,10)===today;set('dailyStatus',claimed?'Daily reward claimed':'Daily reward ready');set('dailyStreak',`${profile.dailyStreak||0} day streak`);const dbtn=$('dailyBtn');if(dbtn)dbtn.disabled=claimed;
 renderFinalDashboard();
}
async function claimDaily(){
 if(demo){profile.coins=(profile.coins||0)+100;profile.xp=(profile.xp||0)+25;profile.dailyStreak=(profile.dailyStreak||0)+1;persistLocalProfile();updateHome();return}
 try{const r=await call('claimDailyReward')({});profile={...profile,...r.data.profile};updateHome();renderProgress('achievements');msg(`Daily reward: +${r.data.coins} coins, +${r.data.xp} XP`)}catch(e){$('dailyStatus').textContent=e.message}
}
const SEASON_REWARDS=[
 [1,100,75,'🪙','75 Coins'],[2,250,0,'🎁','Gift'],[3,400,100,'🪙','100 Coins'],[4,600,0,'🖼️','Flame Frame'],[5,850,150,'🪙','150 Coins'],[6,1100,0,'✨','Spark Effect'],[7,1400,200,'🪙','200 Coins'],[8,1750,0,'🎭','Anime Avatar'],[9,2150,250,'🪙','250 Coins'],[10,2600,0,'🏅','Season Badge'],[11,3100,300,'🪙','300 Coins'],[12,3650,0,'🎉','Party Gift'],[13,4250,350,'🪙','350 Coins'],[14,4900,0,'🌈','Rainbow Frame'],[15,5600,450,'🪙','450 Coins'],[16,6350,0,'💫','Star Effect'],[17,7150,500,'🪙','500 Coins'],[18,8000,0,'🚀','Rocket Gift'],[19,8900,600,'🪙','600 Coins'],[20,10000,0,'👑','Word UNO Champion']]
function seasonTier(xp){let tier=1;for(const r of SEASON_REWARDS)if(xp>=r[1])tier=r[0];return Math.min(20,tier)}
async function claimSeason(tier){if(demo){const xp=Number(profile.seasonXp||profile.xp||0);if(xp<Number(SEASON_REWARDS.find(r=>r[0]===tier)?.[1]||Infinity))return;if(profile.seasonClaims?.[tier])return;profile.seasonClaims={...(profile.seasonClaims||{}),[tier]:true};const reward=SEASON_REWARDS.find(r=>r[0]===tier);if(reward?.[2])profile.coins=(profile.coins||0)+reward[2];persistLocalProfile();renderSeasonPass();updateHome();banner(`Season reward unlocked: ${reward?.[4]||'Reward'}`);playSound('win');return}try{const r=await call('claimSeasonReward')({tier});profile={...profile,...r.data.profile};renderSeasonPass();updateHome();banner(`Season reward unlocked: ${r.data.reward}`);playSound('win')}catch(e){const el=$('passNext');if(el)el.textContent=e.message}}
function renderSeasonPass(){const xp=Number(profile.seasonXp||profile.xp||0),tier=seasonTier(xp),claimed=profile.seasonClaims||{};$('passTier').textContent=tier;$('passXpText').textContent=`${xp.toLocaleString()} / 10,000 XP`;const next=SEASON_REWARDS.find(r=>r[1]>xp);$('passNext').textContent=next?`Next: Tier ${next[0]} · ${next[1]-xp} XP`:'Season complete';$('passBar').style.width=Math.min(100,xp/10000*100)+'%';$('seasonRewards').innerHTML=SEASON_REWARDS.map(([t,need,coins,icon,label])=>{const unlocked=xp>=need,done=!!claimed[t];return `<div class="panel season-reward ${unlocked?'unlocked':''} ${done?'claimed':''}"><div class="tier-num">${t}</div><div class="reward-icon">${icon}</div><b>${esc(label)}</b><small>${need.toLocaleString()} XP</small>${unlocked&&!done?`<button class="mini-btn primary-mini" data-claim-season="${t}">Claim</button>`:done?'<span class="badge">✓ Claimed</span>':'<span class="badge">🔒 Locked</span>'}</div>`}).join('');$('seasonRewards').querySelectorAll('[data-claim-season]').forEach(b=>b.onclick=()=>claimSeason(Number(b.dataset.claimSeason)))}
const ACHIEVEMENTS=[['first_win','First Word','Win your first round','🏆',p=>(p.wins||0)>=1,25],['ten_wins','Getting Started','Win 10 rounds','⭐',p=>(p.wins||0)>=10,50],['fifty_wins','Word Master','Win 50 rounds','👑',p=>(p.wins||0)>=50,150],['hundred_wins','Legendary','Win 100 rounds','💎',p=>(p.wins||0)>=100,300],['games_10','Table Regular','Play 10 games','🎮',p=>(p.games||0)>=10,50],['streak_5','Hot Streak','Reach a 5-win streak','🔥',p=>(p.streak||0)>=5,75],['uno_10','UNO Caller','Call UNO 10 times','📣',p=>(p.unoCalls||0)>=10,75]];
function renderProgress(tab){$('progressTitle').textContent=tab==='achievements'?'Achievements':tab==='inventory'?'Inventory':'Match History';const c=$('progressContent');if(tab==='achievements'){c.innerHTML=ACHIEVEMENTS.map(([id,n,d,icon,fn,reward])=>{const done=!!profile.achievements?.[id]||fn(profile);return `<div class="achievement-card ${done?'':'locked'}"><div style="font-size:2rem">${icon}</div><h3>${esc(n)}</h3><p>${esc(d)}</p><span class="badge">${done?'✓ Completed':'🔒 Locked'} · +${reward} coins</span></div>`}).join('')}else if(tab==='inventory'){const gifts=Object.entries(profile.inventory?.gifts||{}),emotes=Object.entries(profile.inventory?.emotes||{});c.innerHTML=`<div class="inventory-card wide"><h3>🎁 Gifts</h3><p>Items you own for live matches.</p><div class="inventory-items">${gifts.map(([k,v])=>`<div class="inventory-item">${esc(k)}<small>${v} owned</small></div>`).join('')||'<p class="muted">No gifts yet.</p>'}</div><div class="inventory-card wide"><h3>😊 Emotes</h3><p>Your reaction collection.</p><div class="inventory-items">${emotes.map(([k,v])=>`<div class="inventory-item">${esc(k)}<small>${v} owned</small></div>`).join('')}</div></div>`}else{const h=profile.history||[];c.innerHTML=h.length?h.slice(0,20).map(x=>`<div class="history-card"><h3>${x.result==='win'?'🏆 Victory':'🎮 Match'}</h3><p>${esc(x.summary||'Word UNO match')}</p><span class="badge">+${x.coins||0} coins · +${x.xp||0} XP</span><small class="muted" style="display:block;margin-top:7px">${x.date?new Date(x.date).toLocaleString():''}</small></div>`).join(''):'<div class="history-card"><h3>No matches yet</h3><p>Your recent results will appear here.</p></div>'}}
async function refreshProgress(){try{const r=await call('getProgress')({});profile={...profile,...r.data};updateHome()}catch(e){}}

async function createRoom(){if(demo){roomId='LOCAL-'+Math.random().toString(36).slice(2,8).toUpperCase();localStorage.setItem('wordunoRoom',roomId);state={hostId:user.uid,players:[{id:user.uid,name:user.displayName||'Guest',ready:true,online:true}],started:false};renderRoom(state.players);show('room');return}try{const r=await call('createRoom')({});roomId=r.data.code;localStorage.setItem('wordunoRoom',roomId);subscribeRoom(roomId);show('room')}catch(e){alert(e.message)}}
async function joinRoom(){const input=$('roomCode');const code=input?.value.trim().toUpperCase();if(!code)return;if(demo){roomId=code;localStorage.setItem('wordunoRoom',roomId);state={hostId:user.uid,players:[{id:user.uid,name:user.displayName||'Guest',ready:true,online:true}],started:false};renderRoom(state.players);show('room');return}try{const r=await call('joinRoom')({code});roomId=r.data.code;localStorage.setItem('wordunoRoom',roomId);subscribeRoom(roomId);show('room')}catch(e){alert(e.message)}}
async function quickMatch(){if(demo){localStartGame();return}try{clearInterval(matchPollId);show('room');$('roomCodeLabel').textContent='MATCHING';$('shareCode').textContent='SEARCHING';$('roomPlayers').innerHTML='<div class="room-player"><b>Finding players…</b><small>Quick Play</small></div>';$('startRoomBtn').disabled=true;$('readyRoomBtn').disabled=true;const r=await call('quickMatch')({});if(r.data.status==='queued'){roomId='';$('roomStatus').textContent='Searching for players…';matchPollId=setInterval(async()=>{try{const q=await call('getMatchmakingStatus')({});if(!q.data.queued){clearInterval(matchPollId);matchPollId=null;return}$('roomStatus').textContent=`Searching · ${q.data.waiting} player${q.data.waiting===1?'':'s'} waiting`;const again=await call('quickMatch')({});if(again.data.status==='matched'){clearInterval(matchPollId);matchPollId=null;roomId=again.data.code;localStorage.setItem('wordunoRoom',roomId);subscribeRoom(roomId)}}catch(e){}},2500);return}roomId=r.data.code;localStorage.setItem('wordunoRoom',roomId);subscribeRoom(roomId)}catch(e){show('home');alert(e.message)}}
async function restoreRoom(){const code=localStorage.getItem('wordunoRoom');if(!code||!user)return false;try{const s=await getDoc(doc(db,'rooms',code));if(!s.exists()){localStorage.removeItem('wordunoRoom');return false}const r=s.data();if(!(r.playerIds||[]).includes(user.uid)){localStorage.removeItem('wordunoRoom');return false}roomId=code;subscribeRoom(code);show(r.started?'game':'room');return true}catch(e){return false}}
async function startRoom(){try{await call('startRoom')({code:roomId})}catch(e){alert(e.message)}}
async function setReady(){if(!roomId)return;try{roomReady=!roomReady;await call('setRoomReady')({code:roomId,ready:roomReady});$('readyRoomBtn').textContent=roomReady?'✓ Ready':'Ready'}catch(e){roomReady=!roomReady;alert(e.message)}}
async function leaveRoomLobby(){if(!roomId){try{await call('cancelQuickMatch')({})}catch(e){}clearInterval(matchPollId);matchPollId=null;show('home');return}try{await call('leaveRoom')({code:roomId});unsubscribe?.();unsubscribe=null;localStorage.removeItem('wordunoRoom');roomId=null;roomReady=false;show('home')}catch(e){alert(e.message)}}
function roomHeartbeat(){clearInterval(roomHeartbeatId);if(!roomId||!user)return;const beat=()=>call('roomHeartbeat')({code:roomId}).catch(()=>{});beat();roomHeartbeatId=setInterval(beat,15000)}
function setConnection(ok){const a=$('connectionPill'),b=$('gameConnection');[a,b].forEach(x=>{if(!x)return;x.textContent=ok?'● Live':'● Reconnecting…';x.classList.toggle('offline',!ok)})}
function subscribeRoom(id){unsubscribe?.();clearInterval(roomHeartbeatId);unsubscribe=onSnapshot(doc(db,'rooms',id),snap=>{setConnection(true);if(!snap.exists()){localStorage.removeItem('wordunoRoom');roomId=null;show('home');return}state=snap.data();const me=(state.players||[]).find(p=>p.id===user.uid);roomReady=!!me?.ready;if(state.started&&state.state){show('game');roomHeartbeat();renderGame(state.state)}else{show('room');renderRoom(state.players||[]);}},()=>setConnection(false))}
function renderRoom(players){$('roomCodeLabel').textContent=roomId;$('shareCode').textContent=roomId;$('roomPlayers').innerHTML=[0,1,2,3].map(i=>{const p=players[i];return `<div class="room-player ${p?.online===false?'offline':''} ${p?.ready?'ready':''}"><b>${p?'👤 '+esc(p.name):'Waiting…'}</b><small>${p?(i===0?'Host':'Joined'):'Open slot'}</small>${p?`<span class="ready-mark">${p.ready?'✓ READY':p.online===false?'○ OFFLINE':'○ NOT READY'}</span>`:''}</div>`}).join('');$('readyRoomBtn').disabled=!players.some(p=>p.id===user.uid);$('readyRoomBtn').textContent=roomReady?'✓ Ready':'Ready';const allReady=players.length>=2&&players.every(p=>p.ready);$('roomStatus').textContent=players.length<2?'Need at least 2 players.':allReady?'Everyone is ready. Host can start the match.':`${players.length}/4 players · Waiting for everyone to ready up.`;$('startRoomBtn').disabled=!(state?.hostId===user.uid&&players.length>=2&&allReady)}
function legal(c,s){if(c.type==='plus4')return !s.players[s.turn].hand.some(x=>x.type!=='wild'&&x.color===s.chosenColor);return c.type==='wild'||c.color===s.chosenColor||c.word===s.discard.word}
async function play(index){if(!state?.state)return;const s=state.state,me=s.players[s.turn];if(me?.id!==user.uid||s.pendingPlus4)return;const c=me.hand[index];let chosenColor='';if(c.type==='wild'||c.type==='plus4'){chosenColor=await chooseColor();if(!chosenColor)return}if(demo){localPlayCard(index,chosenColor);return}try{await call('playCard')({code:roomId,index,chosenColor})}catch(e){msg(e.message)}}
function chooseColor(){return new Promise(resolve=>{const modal=$('colorModal');modal.classList.remove('hidden');const done=v=>{modal.classList.add('hidden');$('colorModal').querySelectorAll('[data-color]').forEach(b=>b.onclick=null);$('cancelColor').onclick=null;resolve(v)};$('colorModal').querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>done(b.dataset.color));$('cancelColor').onclick=()=>done('')})}
async function resolvePlus4(challenge){try{await call('resolvePlus4')({code:roomId,challenge});}catch(e){msg(e.message)}}
async function challengeUno(){try{await call('challengeUno')({code:roomId})}catch(e){msg(e.message)}}
async function draw(){if(demo){localDraw();return}try{await call('drawCard')({code:roomId})}catch(e){msg(e.message)}}
async function uno(){if(demo){localUno();return}try{await call('callUno')({code:roomId})}catch(e){msg(e.message)}}
function seat(el,p,active){const av=p?.avatar||defaultAvatar;const count=Math.max(0,Number(p?.hand?.length||0));const backs=Math.min(5,Math.max(0,count));el.innerHTML=`<div class="seat-inner ${active?'active':''}"><div class="avatar seat-avatar">${avatarMarkup('seat',av)}</div><div class="seat-info"><b>${esc(p?.name||'Waiting…')}</b><small>${count} cards${active?' · YOUR TURN':''}</small></div></div><div class="mini-hand">${Array.from({length:backs},(_,i)=>`<i style="--i:${i}"><span>WU</span></i>`).join('')}</div>`;el.style.boxShadow='none'}
function cardLabel(c){const map={skip:'⛔',reverse:'↔',plus2:'+2',plus4:'+4',wild:'★'};return c?.type&&map[c.type]?`<span class="card-icon">${map[c.type]}</span><span class="card-word">${esc(c.word||c.type.toUpperCase())}</span>`:`<span class="card-word">${esc(c?.word||'WORD')}</span>`}
function showWin(s){if(!s.over||winShown)return;winShown=true;const ev=s.lastEvent||{};const me=user?.uid;const winner=ev.playerName||s.players?.find(p=>p.id===ev.playerId)?.name||'Winner';const mine=ev.playerId===me;$('winTitle').textContent=mine?'You Won!':`${winner} Won!`;$('winSummary').textContent=mine?'Excellent round. Your rewards are being added to your profile.':`${winner} finished the round first.`;const r=(s.settlement||[]).find(x=>x.id===me);$('winCoins').textContent=`+${r?.coins||0}`;$('winXp').textContent=`+${r?.xp||0}`;$('winModal').classList.remove('hidden')}
function renderGame(s){if(!s.over)winShown=false;handleGameEvent(s);const me=s.players.findIndex(p=>p.id===user.uid);populateGiftTargets(s);if(me<0)return;const ordered=[0,1,2,3].map((_,i)=>s.players[(me+i)%s.players.length]);if(ordered[0])ordered[0].avatar=avatarData();ordered.forEach(p=>{if(p&&classicAvatarCache[p.id])p.avatar=classicAvatarCache[p.id]});renderClassicTablePlayers(ordered);if(db&&!classicAvatarHydrating){classicAvatarHydrating=true;hydrateClassicPlayerAvatars(ordered).then(()=>{classicAvatarHydrating=false;renderClassicTablePlayers(ordered);ordered.forEach((p,i)=>{if(p&&classicAvatarCache[p.id])p.avatar=classicAvatarCache[p.id]});seat($('pTop'),ordered[2],s.turn===s.players.indexOf(ordered[2]));seat($('pLeft'),ordered[1],s.turn===s.players.indexOf(ordered[1]));seat($('pRight'),ordered[3],s.turn===s.players.indexOf(ordered[3]));seat($('pMe'),ordered[0],s.turn===s.players.indexOf(ordered[0]))}).catch(()=>{classicAvatarHydrating=false})}seat($('pTop'),ordered[2],s.turn===s.players.indexOf(ordered[2]));seat($('pLeft'),ordered[1],s.turn===s.players.indexOf(ordered[1]));seat($('pRight'),ordered[3],s.turn===s.players.indexOf(ordered[3]));seat($('pMe'),ordered[0],s.turn===s.players.indexOf(ordered[0]));const c=s.discard;$('discard').className=`card ${c.color} ${c.type||'word'}`;$('discard').innerHTML=cardLabel(c);$('colorHint').textContent=`COLOR: ${s.chosenColor.toUpperCase()}`;$('turnText').textContent=s.over?'Round complete':s.pendingPlus4?'Choose: Challenge +4 or Accept +4':s.players[s.turn]?.id===user.uid?(s.drawnCardId?'Play the drawn card or wait':'Your turn'):'Waiting for '+s.players[s.turn]?.name;$('handCount').textContent=`${ordered[0].hand.length} cards`;$('hand').innerHTML='';ordered[0].hand.forEach((c,i)=>{const b=document.createElement('button');b.className=`hand-card ${c.color} ${c.type||'word'} ${legal(c,s)?'playable':''}`;b.innerHTML=cardLabel(c);b.disabled=s.players[s.turn]?.id!==user.uid||s.over||!!s.pendingPlus4||!!(s.drawnCardId&&c.id!==s.drawnCardId)||!legal(c,s);b.onclick=()=>play(i);$('hand').appendChild(b)});$('drawBtn').disabled=s.players[s.turn]?.id!==user.uid||s.over||!!s.pendingPlus4||!!s.drawnCardId;$('unoBtn').disabled=s.over||s.unoTarget!==user.uid;$('challengeBar').classList.toggle('hidden',s.over||(!s.pendingPlus4&&!s.unoTarget));$('challengePlus4Btn').classList.toggle('hidden',!(s.pendingPlus4&&s.pendingPlus4.targetId===user.uid));$('acceptPlus4Btn').classList.toggle('hidden',!(s.pendingPlus4&&s.pendingPlus4.targetId===user.uid));$('challengeUnoBtn').classList.toggle('hidden',!(s.unoTarget&&s.unoTarget!==user.uid&&!s.pendingPlus4));if(s.pendingPlus4)$('challengeText').textContent='The +4 was played. Challenge it if the previous color was available.';else if(s.unoTarget)$('challengeText').textContent='A player has 1 card and did not call UNO.';msg(s.lastAction||'Match the color or the word.');showWin(s);startTimer(s)}
function startTimer(s){clearInterval(timerId);let n=30;$('timer').textContent=s.pendingPlus4?'--':n;if(s.over||s.pendingPlus4||s.players[s.turn]?.id!==user.uid)return;timerId=setInterval(()=>{n--;$('timer').textContent=n;if(n<=0){clearInterval(timerId);draw()}},1000)}


