 ['avatar_cartoon_fox','Cartoon • Fox','data:image/svg+xml;base64,',700],['avatar_cartoon_panda','Cartoon • Panda','data:image/svg+xml;base64,',700],['avatar_boy_cap','Cartoon • Cap Boy','data:image/svg+xml;base64,',650],['avatar_girl_sky','Cartoon • Sky Girl','data:image/svg+xml;base64,',750],
 ['avatar_boy_mint','Anime Boy • Mint','data:image/svg+xml;base64,',900],['avatar_girl_sun','Anime Girl • Sun','data:image/svg+xml;base64,',850],['avatar_cartoon_cat','Cartoon • Cat','data:image/svg+xml;base64,',700],['avatar_boy_silver','Anime Boy • Silver','data:image/svg+xml;base64,',1000]
