const FRAMES=[['frame_classic','Classic WU',0],['frame_flame','Flame Burst',500],['frame_rainbow','Rainbow Rush',700],['frame_neon','Neon Pulse',900],['frame_royal','Royal Prism',1200],['frame_pixel','Pixel Pop',850]];
const EFFECTS=[['effect_spark','Sparkle','✨',400],['effect_burst','Burst','💥',650],['effect_confetti','Confetti','🎊',800],['effect_star','Star Glow','⭐',550],['effect_lightning','Lightning','⚡',950],['effect_rainbow','Rainbow Trail','🌈',1100]];
const CARD_BACKS=[['cardback_aurora','Aurora','🌌',750],['cardback_arcade','Arcade','🕹️',900],['cardback_candy','Candy','🍬',650]];
const TABLE_THEMES=[['table_neon','Neon Arena','💠',1000],['table_sunset','Sunset Lounge','🌅',850],['table_cosmic','Cosmic Room','🌠',1250]];
