const defaultAvatar={avatarId:'avatar_boy_ember',frameId:'frame_classic',effectId:'effect_spark'};
let shopFilter='featured';
function owned(id){return id==='avatar_boy_ember'||id==='frame_classic'||(profile.ownedCosmetics||[]).includes(id)}
function avatarData(){return {...defaultAvatar,...(profile.avatar||{})}}
function avatarMarkup(size='small',obj=avatarData()){
 const a=AVATARS.find(x=>x[0]===obj.avatarId)||AVATARS[0];
 return `<div class="avatar-wrap ${size}"><img class="avatar-img" src="${a[2]}" alt="${esc(a[1])}"><div class="avatar-frame ${esc(obj.frameId||'frame_classic')}"></div><div class="avatar-effect ${esc(obj.effectId||'effect_spark')}" data-symbol="${(EFFECTS.find(x=>x[0]===obj.effectId)||EFFECTS[0])[2]}"></div></div>`;
}
function renderProfileAvatars(){ const a=avatarData(); [['topAvatar','top',a],['homeAvatar','hero',a],['studioAvatar','studio',editingAvatar]].forEach(([id,kind,data])=>{const e=$(id);if(e)e.innerHTML=avatarMarkup(kind,data)});const n=$('studioName');if(n)n.textContent=profile.displayName||'Player'; }
function renderStyleTab(tab){ const c=$('styleGrid');if(!c)return; const rows=tab==='avatars'?AVATARS.map(([id,n,img,price])=>({id,n,price,visual:`<img src="${img}" alt="${esc(n)}">`})):tab==='frames'?FRAMES.map(([id,n,price])=>({id,n,price,visual:`<div class="frame-swatch ${id}">◎</div>`})):EFFECTS.map(([id,n,sym,price])=>({id,n,price,visual:`<div class="effect-swatch ${id}">${sym}</div>`})); c.innerHTML=rows.map(x=>`<button class="style-card ${editingAvatar[tab==='avatars'?'avatarId':tab==='frames'?'frameId':'effectId']===x.id?'selected':''}" data-style="${x.id}">${x.visual}<small>${esc(x.n)}</small><span class="owned-cosmetic">${owned(x.id)?'Owned':`🪙 ${x.price}`}</span></button>`).join(''); c.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>selectStyle(tab,b.dataset.style)); }
function selectStyle(tab,id){ const field=tab==='avatars'?'avatarId':tab==='frames'?'frameId':'effectId'; if(!owned(id)){show('shop');shopFilter=tab==='avatars'?'avatars':tab==='frames'?'frames':'effects';renderShop();return} editingAvatar={...editingAvatar,[field]:id};renderProfileAvatars();renderStyleTab(tab); }
async function saveAvatar(){ if(!user)return; if(demo){profile.avatar={...editingAvatar};persistLocalProfile();renderProfileAvatars();const m=$('avatarMsg');if(m)m.textContent='Style saved on this device.';updateHome();return} try{const r=await call('equipCosmetic')({cosmeticId:editingAvatar.avatarId}); if(editingAvatar.frameId)await call('equipCosmetic')({cosmeticId:editingAvatar.frameId}); if(editingAvatar.effectId)await call('equipCosmetic')({cosmeticId:editingAvatar.effectId}); profile.avatar={...editingAvatar};renderProfileAvatars();$('avatarMsg').textContent='Style saved for your profile.';updateHome()}catch(e){$('avatarMsg').textContent=e.message} }
const SHOP=[...AVATARS.map(([id,name,img,price])=>({id,name,type:'avatars',img,price,tag:'Character',icon:'🎭'})),...FRAMES.map(([id,name,price])=>({id,name,type:'frames',price,tag:'Frame',icon:'◎'})),...EFFECTS.map(([id,name,sym,price])=>({id,name,type:'effects',price,tag:'Effect',icon:sym})),...CARD_BACKS.map(([id,name,sym,price])=>({id,name,type:'cardbacks',price,tag:'Card Back',icon:sym})),...TABLE_THEMES.map(([id,name,sym,price])=>({id,name,type:'tables',price,tag:'Table Theme',icon:sym})),...BADGES.map(([id,name,sym,price])=>({id,name,type:'badges',price,tag:'Badge',icon:sym}))];
const SHOP_FILTERS=[['featured','✨ Featured'],['avatars','🎭 Characters'],['frames','🖼️ Frames'],['effects','💫 Effects'],['cardbacks','🃏 Card Backs'],['tables','🌌 Tables'],['badges','🏅 Badges']];
function renderShop(){ const sc=$('shopCoins');if(sc)sc.textContent=profile.coins??0; const filters=$('shopFilters'); if(filters)filters.innerHTML=SHOP_FILTERS.map(([id,label])=>`<button class="shop-filter ${shopFilter===id?'active':''}" data-shop-filter="${id}">${label}</button>`).join(''); const pool=shopFilter==='featured'?SHOP.filter((_,i)=>i<8||i%5===0):SHOP.filter(x=>x.type===shopFilter); const grid=$('shopGrid');if(!grid)return;grid.innerHTML=pool.map(x=>{const isOwned=owned(x.id), equipped=(profile.equippedCosmetics||{})[x.type==='avatars'?'avatar':x.type==='frames'?'frame':x.type==='effects'?'effect':x.type.slice(0,-1)]; const visual=x.img?`<img src="${x.img}" alt="${esc(x.name)}">`:`<div class="shop-visual">${x.icon}</div>`;return `<div class="shop-card ${isOwned?'owned':''} ${equipped===x.id?'equipped':''}">${visual}<span class="tag">${x.tag}</span><h3>${esc(x.name)}</h3><p>${equipped===x.id?'Equipped':isOwned?'In your collection.':'Original Word UNO cosmetic.'}</p><div class="price">${isOwned?'✓ OWNED':`🪙 ${x.price}`}</div><button class="primary-btn" data-shop-action="${x.id}">${equipped===x.id?'Equipped':isOwned?'Equip':'Unlock'}</button></div>`}).join(''); document.querySelectorAll('[data-shop-filter]').forEach(b=>b.onclick=()=>{shopFilter=b.dataset.shopFilter;renderShop()}); grid.querySelectorAll('[data-shop-action]').forEach(b=>b.onclick=()=>shopAction(b.dataset.shopAction)); }
async function shopAction(id){ const item=SHOP.find(x=>x.id===id); if(!item)return; if(demo){const wasOwned=owned(id);if(!wasOwned){if(Number(profile.coins||0)<item.price)return banner('Not enough coins');profile.coins=Number(profile.coins||0)-item.price;profile.ownedCosmetics=[...(profile.ownedCosmetics||[]),id];}const field=item.type==='avatars'?'avatarId':item.type==='frames'?'frameId':item.type==='effects'?'effectId':null;if(field){profile.avatar={...(profile.avatar||{}),[field]:id};profile.equippedCosmetics={...(profile.equippedCosmetics||{}),[item.type==='avatars'?'avatar':item.type==='frames'?'frame':'effect']:id};}persistLocalProfile();renderShop();renderProfileAvatars();updateHome();banner(wasOwned?'Cosmetic equipped!':'Cosmetic unlocked!');return} if(!owned(id)){try{const r=await call('buyCosmetic')({cosmeticId:id});profile.coins=r.data.coins;profile.ownedCosmetics=[...(profile.ownedCosmetics||[]),id];banner('Cosmetic unlocked!')}catch(e){banner(e.message);return}} try{const r=await call('equipCosmetic')({cosmeticId:id});profile.avatar={...(profile.avatar||{}),...(r.data.avatar||{})};profile.equippedCosmetics=r.data.equippedCosmetics||profile.equippedCosmetics||{};renderShop();renderProfileAvatars();updateHome()}catch(e){banner(e.message)} }
const PROFILE_TITLES=[['word-starter','Word Starter','Begin your Word UNO journey'],['table-regular','Table Regular','A familiar face at the table'],['color-chaser','Color Chaser','Match colors with style'],['uno-caller','UNO Caller','Make your UNO moments count'],['word-master','Word Master','A title for dedicated players']];
const DAILY_MISSIONS=[
 ['d_games','Play 2 games','games',2,40],
 ['d_win','Win 1 game','wins',1,60],
 ['d_uno','Call UNO 1 time','unoCalls',1,35]
];
const WEEKLY_MISSIONS=[
 ['w_games','Play 10 games','games',10,120],
 ['w_wins','Win 5 games','wins',5,180],
 ['w_streak','Reach a 3-win streak','streak',3,150]
];
function missionProgress(key){return Number(profile[key]||0)}
function missionMarkup(m){const [id,name,key,target,reward]=m;const value=Math.min(target,missionProgress(key));const pct=Math.round(value/target*100);return `<div class="mission-row"><div class="mission-icon">${pct>=100?'✓':'★'}</div><div class="mission-main"><b>${esc(name)}</b><div class="mission-track"><span style="width:${pct}%"></span></div><small>${value}/${target} · +${reward} coins</small></div><span class="mission-pct">${pct}%</span></div>`}
function renderEvents(){
 const d=$('dailyMissions'),w=$('weeklyMissions');if(!d||!w)return;
 d.innerHTML=DAILY_MISSIONS.map(missionMarkup).join('');w.innerHTML=WEEKLY_MISSIONS.map(missionMarkup).join('');
 const chosen=localStorage.getItem('wordunoTitle')||'word-starter';
 const titlesEl=$('titleChoices');if(!titlesEl)return;titlesEl.innerHTML=PROFILE_TITLES.map(([id,name,desc])=>`<button class="title-chip ${id===chosen?'selected':''}" data-title="${id}"><b>${esc(name)}</b><small>${esc(desc)}</small></button>`).join('');
 titlesEl.querySelectorAll('[data-title]').forEach(b=>b.onclick=()=>{localStorage.setItem('wordunoTitle',b.dataset.title);renderEvents();$('titleMsg').textContent='Profile title saved on this device.'});
}
const SEASON_BOARD=[['Aiko','girl_rose.svg',1860],['Kai','boy_azure.svg',1725],['Mina','girl_sky.svg',1610],['Rex','boy_ember.svg',1495],['Luna','girl_violet.svg',1380],['Jax','boy_cap.svg',1240],['Panda','cartoon_panda.svg',1120],['Fox','cartoon_fox.svg',980]];
function renderLeaderboard(){if(!$('leaderRows'))return;const xp=Number(profile.xp||0),wins=Number(profile.wins||0),games=Number(profile.games||0),uno=Number(profile.unoCalls||0);const board=[...SEASON_BOARD,{name:profile.displayName||'Player',avatar:null,xp}].sort((a,b)=>b.xp-a.xp);const me=board.findIndex(x=>x.avatar===null);$('myRank').textContent=`Your Rank · #${me+1}`;$('rankXp').textContent=xp;$('rankWins').textContent=wins;$('rankGames').textContent=games;$('seasonBar').style.width=Math.min(100,(xp%1000)/10)+'%';$('statWins').textContent=wins;$('statGames').textContent=games;$('statUno').textContent=uno;$('statCoins').textContent=profile.coins||0;const title=localStorage.getItem('wordunoTitle')||'word-starter';const names={'word-starter':'Word Starter','table-regular':'Table Regular','color-chaser':'Color Chaser','uno-caller':'UNO Caller','word-master':'Word Master'};$('profileTitlePill').textContent=names[title]||'Word Starter';$('leaderRows').innerHTML=board.slice(0,8).map((x,i)=>`<div class="leader-row"><div class="leader-rank">#${i+1}</div><div class="leader-main"><div class="avatar">${x.avatar?`<img src="assets/${x.avatar}" alt="">`:'⭐'}</div><div><b>${esc(x.name)}</b><small class="muted">Season player</small></div></div><div class="leader-score"><b>${x.xp.toLocaleString()}</b><small>XP</small></div></div>`).join('')}

function renderNotifications(filter='All'){const target=$('notificationList');if(!target)return;const list=[['🎁','Gifts & emotes','Live gifts can appear during your matches.','Rewards'],['🏆','Achievements','Complete milestones to earn coins and XP.','Game'],['🎁','Daily reward','Claim your daily coins and XP from Home.','Rewards'],['👥','Friends','Send requests and invite friends to parties.','Social'],['🎨','Avatar Studio','Choose an anime, cartoon, frame and effect.','Game']];const pool=filter==='All'?list:list.filter(x=>x[3]===filter);target.innerHTML=pool.map(x=>`<div class="notification-row"><div class="notification-icon">${x[0]}</div><div><b>${x[1]}</b><small>${x[2]}</small></div></div>`).join('')||'<p class="muted">No notifications in this category.</p>';document.querySelectorAll('#notifications .notification-tabs .studio-tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('#notifications .notification-tabs .studio-tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderNotifications(b.textContent.trim())})}
function initSettings(){
 const s=$('settingSound'),fx=$('settingFx'),motion=$('settingMotion'),friends=$('settingFriends'),invites=$('settingInvites'),vibration=$('settingVibration'),voice=$('settingVoice');
 if(s)s.checked=soundOn; if(fx)fx.checked=localStorage.getItem('wordunoFx')!=='off'; if(motion)motion.checked=localStorage.getItem('wordunoMotion')==='on';
 if(friends)friends.checked=localStorage.getItem('wordunoAllowFriends')!=='off'; if(invites)invites.checked=localStorage.getItem('wordunoAllowInvites')!=='off';
 if(vibration)vibration.checked=localStorage.getItem('wordunoVibration')!=='off'; if(voice)voice.checked=localStorage.getItem('wordunoVoice')!=='off';
 s&&(s.onchange=()=>{soundOn=s.checked;localStorage.setItem('wordunoSound',soundOn?'on':'off');if($('soundBtn'))$('soundBtn').textContent=soundOn?'🔊':'🔇';if(soundOn)tone(660,.08)});
 fx&&(fx.onchange=()=>localStorage.setItem('wordunoFx',fx.checked?'on':'off'));
 motion&&(motion.onchange=()=>localStorage.setItem('wordunoMotion',motion.checked?'on':'off'));
 vibration&&(vibration.onchange=()=>localStorage.setItem('wordunoVibration',vibration.checked?'on':'off'));
 voice&&(voice.onchange=()=>localStorage.setItem('wordunoVoice',voice.checked?'on':'off'));
 const safety=async()=>{const allowFriendRequests=friends?friends.checked:true,allowPartyInvites=invites?invites.checked:true;localStorage.setItem('wordunoAllowFriends',allowFriendRequests?'on':'off');localStorage.setItem('wordunoAllowInvites',allowPartyInvites?'on':'off');if(!demo){try{await call('updateSafetySettings')({allowFriendRequests,allowPartyInvites})}catch(e){banner(e.message)}}};
 friends&&(friends.onchange=safety);invites&&(invites.onchange=safety);
}

const EMOTES=[['😂','Laugh'],['🔥','Fire'],['😎','Cool'],['😱','Wow'],['👏','Clap'],['❤️','Love']];
const GIFTS=[['🎁','Gift'],['💎','Diamond'],['🚀','Rocket'],['👑','Crown'],['🎉','Party']];
document.getElementById('closeWinBtn')?.addEventListener('click',()=>document.getElementById('winModal')?.classList.add('hidden'));
$('leaderboardBtn')?.addEventListener('click',()=>{renderLeaderboard();show('leaderboard')});
$('seasonPassBtn')?.addEventListener('click',async()=>{try{await refreshProgress()}catch(e){}renderSeasonPass();show('seasonpass')});
function fillMenus(){
 const em=$('emoteMenu'),gm=$('giftMenu');if(!em||!gm)return;
 em.innerHTML=EMOTES.map(([e,n])=>`<button data-e="${e}">${e} ${n}</button>`).join('');
 gm.innerHTML=GIFTS.map(([e,n])=>`<button data-g="${e}">${e} ${n}</button>`).join('');
 em.querySelectorAll('[data-e]').forEach(b=>b.onclick=()=>sendReaction('emote',b.dataset.e));
 gm.querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>sendReaction('gift',b.dataset.g));
}
function populateGiftTargets(s){const sel=$('giftTarget');if(!sel)return;const me=user.uid;sel.innerHTML='<option value="">Choose player</option>'+(s.players||[]).filter(p=>p.id!==me).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}
async function sendReaction(kind,value){
 if(!roomId)return;document.querySelectorAll('.reaction-menu').forEach(x=>x.classList.add('hidden'));
 const toId=kind==='gift'?$('giftTarget').value:'';
 if(kind==='gift'&&!toId)return $('socialStatus').textContent='Choose a player to receive the gift.';
 try{await call('sendReaction')({code:roomId,kind,value,toId});$('socialStatus').textContent=kind==='gift'?'Gift sent!':'Reaction sent!'}catch(e){$('socialStatus').textContent=e.message}
}
function showFx(kind,value,from,targetId){
 const layer=$('fxLayer'),x=document.createElement('div');x.className='fx '+(kind==='gift'?'giftFx':'')+(targetId?' gift-target':'');x.textContent=value;x.title=from||'';
 if(targetId){const target=state?.state?.players?.find(p=>p.id===targetId);const idx=state?.state?.players?.findIndex(p=>p.id===targetId);if(target&&idx>=0){const me=state.state.players.findIndex(p=>p.id===user.uid);const seatIndex=(idx-me+4)%4;const vectors=[[0,-130],[-190,-10],[0,120],[190,-10]];const [tx,ty]=vectors[seatIndex]||[0,0];x.style.setProperty('--tx',tx+'px');x.style.setProperty('--ty',ty+'px')}}
 layer.appendChild(x);setTimeout(()=>x.remove(),1900)
}
function startReactionListener(){
 // Reaction events are append-only room subcollection documents; every connected player sees them.
 if(!roomId||!db)return;
 const q=query(collection(db,'rooms',roomId,'reactions'),orderBy('createdAt','desc'),limit(8));
 return onSnapshot(q,snap=>snap.docChanges().reverse().forEach(ch=>{if(ch.type==='added'){const r=ch.doc.data();showFx(r.kind,r.value,r.fromName,r.toId)}}))
}

let reactionUnsub=null;
function wireReactionListener(){reactionUnsub?.();reactionUnsub=startReactionListener()}

function stopSocialListeners(){friendUnsub?.();inviteUnsub?.();partyUnsub?.();reactionUnsub?.();friendUnsub=inviteUnsub=partyUnsub=reactionUnsub=null}
function startSocialListeners(){
 if(!db||!user)return;
 friendUnsub=onSnapshot(query(collection(db,'friendRequests'),where('toId','==',user.uid),where('status','==','pending'),limit(25)),renderRequests);
 inviteUnsub=onSnapshot(query(collection(db,'partyInvites'),where('toId','==',user.uid),where('status','==','pending'),limit(25)),renderInvites);
}
function renderRequests(snap){$('requestCount').textContent=snap.size;$('requests').innerHTML=snap.empty?'<p class="muted">No pending requests.</p>':snap.docs.map(d=>{const r=d.data();return `<div class="invite-row"><div><b>${esc(r.fromName)}</b><small class="muted"> wants to be friends</small></div><div class="friend-actions"><button class="mini-btn" data-accept="${d.id}">Accept</button><button class="mini-btn" data-reject="${d.id}">Decline</button></div></div>`}).join('');$('requests').querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>respondFriend(b.dataset.accept,'accept'));$('requests').querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>respondFriend(b.dataset.reject,'reject'))}
async function respondFriend(id,action){try{await call('respondFriendRequest')({requestId:id,action}) ;loadFriends()}catch(e){alert(e.message)}}
async function removeFriend(friendId){if(!confirm('Remove this friend?'))return;try{await call('removeFriend')({friendId});loadFriends()}catch(e){alert(e.message)}}
async function sendFriend(){const input=$('friendName'),name=input?.value.trim();if(!name)return;const out=$('friendMsg');if(out)out.textContent='Sending…';if(demo){const key='wordunoLocalFriends_'+(user?.uid||'guest');const friends=JSON.parse(localStorage.getItem(key)||'[]');if(!friends.some(f=>f.displayName.toLowerCase()===name.toLowerCase()))friends.push({id:'friend_'+Date.now(),displayName:name,online:false});localStorage.setItem(key,JSON.stringify(friends));if(input)input.value='';if(out)out.textContent='Friend saved on this device.';renderFriends(friends);return}try{await call('sendFriendRequest')({displayName:name});if(input)input.value='';if(out)out.textContent='Request sent.'}catch(e){if(out)out.textContent=e.message}}
async function loadFriends(){if(demo){const key='wordunoLocalFriends_'+(user?.uid||'guest');renderFriends(JSON.parse(localStorage.getItem(key)||'[]'));const inv=$('invites');if(inv)inv.innerHTML='<p class="muted">No pending party invitations.</p>';return}try{const r=await call('listFriends')({});renderFriends(r.data.friends||[])}catch(e){const out=$('friends');if(out)out.textContent=e.message}}
function renderFriends(friends){$('friends').innerHTML=friends.length?friends.map(f=>`<div class="friend-row"><div class="friend-main"><div class="avatar">${esc((f.displayName||'P')[0].toUpperCase())}</div><div><b>${esc(f.displayName)}</b><small class="muted">${f.online?'🟢 Online':'Offline'}</small></div></div><div class="friend-actions"><button class="mini-btn" data-invite="${esc(f.id)}">Invite</button><button class="mini-btn" data-remove="${esc(f.id)}">Remove</button></div></div>`).join(''):'<p class="muted">No friends yet.</p>';$('friends').querySelectorAll('[data-invite]').forEach(b=>b.onclick=()=>inviteToParty(b.dataset.invite));$('friends').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>removeFriend(b.dataset.remove))}
function renderInvites(snap){$('invites').innerHTML=snap.empty?'<p class="muted">No pending party invitations.</p>':snap.docs.map(d=>{const r=d.data();return `<div class="invite-row"><div><b>${esc(r.fromName)}</b><small class="muted"> invited you to party ${esc(r.partyId)}</small></div><button class="mini-btn" data-joininvite="${d.id}">Join</button></div>`}).join('');$('invites').querySelectorAll('[data-joininvite]').forEach(b=>b.onclick=()=>acceptPartyInvite(b.dataset.joininvite))}
async function inviteToParty(friendId){if(!partyId)return alert('Create a party first.');try{await call('inviteToParty')({partyId,friendId});alert('Invitation sent.')}catch(e){alert(e.message)}}
async function createParty(){if(demo){partyId='LOCALPARTY-'+Math.random().toString(36).slice(2,8).toUpperCase();localStorage.setItem('wordunoParty',partyId);const members=[{id:user.uid,name:user.displayName||'Guest'}];$('partyCode').textContent=partyId.slice(-6);$('partyMembers').innerHTML=members.map(m=>`<div class="member-row"><span>👤 ${esc(m.name)}</span><small class="muted">Host</small></div>`).join('');$('startPartyBtn').disabled=false;return}try{const r=await call('createParty')({});partyId=r.data.partyId;localStorage.setItem('wordunoParty',partyId);subscribeParty(partyId);show('party')}catch(e){alert(e.message)}}
async function acceptPartyInvite(inviteId){try{const r=await call('acceptPartyInvite')({inviteId});partyId=r.data.partyId;localStorage.setItem('wordunoParty',partyId);subscribeParty(partyId);show('party')}catch(e){alert(e.message)}}
function subscribeParty(id){partyUnsub?.();partyUnsub=onSnapshot(doc(db,'parties',id),snap=>{if(!snap.exists())return;const p=snap.data();renderParty(p);})}
async function renderParty(p){
 $('partyCode').textContent=p.id.slice(-6).toUpperCase();
 $('partyMembers').innerHTML=(p.members||[]).map(m=>`<div class="member-row"><span>👤 ${esc(m.name)}</span><small class="muted">${m.id===p.hostId?'Host':''}</small></div>`).join('');
 $('startPartyBtn').disabled=p.hostId!==user.uid||p.members.length<2;
 try{const r=await call('listFriends')({});const friends=r.data.friends||[];
   $('partyFriends').innerHTML=friends.length?friends.map(f=>`<div class="friend-row"><div class="friend-main"><div class="avatar">${esc((f.displayName||'P')[0].toUpperCase())}</div><div><b>${esc(f.displayName)}</b><small class="muted">${f.online?' Online':' Offline'}</small></div></div><button class="mini-btn" data-pinvite="${esc(f.id)}" ${p.members.some(m=>m.id===f.id)?'disabled':''}>Invite</button></div>`).join(''):'<p class="muted">Add friends first.</p>';
   $('partyFriends').querySelectorAll('[data-pinvite]').forEach(b=>b.onclick=()=>inviteToParty(b.dataset.pinvite));
 }catch(e){$('partyFriends').textContent=e.message}
}
async function leaveParty(){if(!partyId)return;if(demo){localStorage.removeItem('wordunoParty');partyId=null;show('home');return}try{await call('leaveParty')({partyId});localStorage.removeItem('wordunoParty');partyId=null;partyUnsub?.();partyUnsub=null;show('home')}catch(e){alert(e.message)}}
