function makeLocalCard(word,color='blue',type='word'){return{id:'local_'+Math.random().toString(36).slice(2),word,color,type}}
function makeLocalGame(){
 const colors=['red','blue','green','yellow'];
 const words=['APPLE','HOUSE','RIVER','MOON','STAR','GREEN','BOOK','CLOUD','SUN','TREE','LIGHT','FIRE'];
 const players=[
  {id:user?.uid||'guest',name:user?.displayName||'Guest',hand:[],avatar:avatarData()},
  {id:'bot_1',name:'Aiko',hand:[],avatar:{avatarId:'avatar_girl_rose',frameId:'frame_classic',effectId:'effect_spark'}},
  {id:'bot_2',name:'Kai',hand:[],avatar:{avatarId:'avatar_boy_azure',frameId:'frame_classic',effectId:'effect_spark'}},
  {id:'bot_3',name:'Mina',hand:[],avatar:{avatarId:'avatar_girl_sky',frameId:'frame_classic',effectId:'effect_spark'}}
 ];
 players.forEach((p,pi)=>{for(let i=0;i<7;i++)p.hand.push(makeLocalCard(words[(pi*3+i)%words.length],colors[(pi+i)%colors.length]));});
 return {players,turn:0,discard:makeLocalCard('APPLE','red'),chosenColor:'red',over:false,pendingPlus4:null,unoTarget:null,lastEvent:null,lastAction:'Match the color or the word.',drawnCardId:null,settlement:[]};
}
function finishLocalGame(s,winnerId){s.over=true;s.turn=0;s.lastEvent={id:'local_'+Date.now(),type:'card_play',cardType:'word',playerId:winnerId,playerName:s.players.find(p=>p.id===winnerId)?.name||'Winner'};s.settlement=s.players.map(p=>({id:p.id,coins:p.id===winnerId?250:25,xp:p.id===winnerId?200:50}));if(winnerId===user?.uid){profile.wins=(profile.wins||0)+1;profile.games=(profile.games||0)+1;profile.coins=(profile.coins||0)+250;profile.xp=(profile.xp||0)+200;profile.streak=(profile.streak||0)+1;persistLocalProfile();updateHome();playSound('win');confetti();}}
function localBotTurn(s){if(s.over)return;const bot=s.players[s.turn];if(!bot)return;const idx=bot.hand.findIndex(c=>legal(c,s));if(idx>=0){const c=bot.hand.splice(idx,1)[0];s.discard=c;s.chosenColor=c.color||s.chosenColor;s.lastEvent={id:'local_'+Date.now(),type:'card_play',cardType:c.type,word:c.word,playerId:bot.id,playerName:bot.name};s.lastAction=`${bot.name} played ${c.word}.`;if(!bot.hand.length){finishLocalGame(s,bot.id);renderGame(s);return;}}else{const c=makeLocalCard('WORD',s.chosenColor||'blue');bot.hand.push(c);s.lastAction=`${bot.name} drew a card.`;}s.turn=(s.turn+1)%s.players.length;renderGame(s);if(!s.over&&s.turn!==0)setTimeout(()=>localBotTurn(s),650);}
function localPlayCard(index,chosenColor=''){const s=state?.state;if(!s||s.over||s.turn!==0)return;const me=s.players[0],c=me.hand[index];if(!c||!legal(c,s))return;if(c.type==='wild'||c.type==='plus4')s.chosenColor=chosenColor||s.chosenColor;me.hand.splice(index,1);s.discard=c;s.lastEvent={id:'local_'+Date.now(),type:'card_play',cardType:c.type,word:c.word,playerId:me.id,playerName:me.name};s.lastAction=`You played ${c.word||'a card'}.`;s.drawnCardId=null;if(!me.hand.length){finishLocalGame(s,me.id);renderGame(s);return;}s.turn=1;renderGame(s);setTimeout(()=>localBotTurn(s),700);}
function localDraw(){const s=state?.state;if(!s||s.over||s.turn!==0)return;const c=makeLocalCard('WORD',['red','blue','green','yellow'][Math.floor(Math.random()*4)]);s.players[0].hand.push(c);s.drawnCardId=c.id;s.lastAction='You drew a card.';renderGame(s);}
function localUno(){const s=state?.state;if(!s||s.over||s.turn!==0)return;if(s.players[0].hand.length<=2){s.unoTarget=null;s.lastEvent={id:'local_'+Date.now(),type:'uno',playerId:user?.uid,playerName:user?.displayName||'Guest'};s.lastAction='UNO!';renderGame(s);}}

