// V39.9 — Complete UNO-style home interaction layer.
// Every visible control on the master-art home screen is independently tappable.
// Only Profile leaves the home screen. All other controls give immediate feedback
// in-place, just like a game lobby control: press state + contextual toast.
function homeFeedback(title, hint=''){
  const root=document.querySelector('#finalDashboard .uno-home');
  if(!root)return;
  let box=root.querySelector('.cw-home-feedback');
  if(!box){
    box=document.createElement('div');
    box.className='cw-home-feedback';
    root.appendChild(box);
  }
  box.innerHTML=`<span class="cw-feedback-title"></span><span class="cw-feedback-hint"></span>`;
  box.querySelector('.cw-feedback-title').textContent=title;
  box.querySelector('.cw-feedback-hint').textContent=hint||'Selected';
  box.classList.remove('show');
  void box.offsetWidth;
  box.classList.add('show');
  clearTimeout(window.__cwHomeFeedbackTimer);
  window.__cwHomeFeedbackTimer=setTimeout(()=>box.classList.remove('show'),1250);
}
function homePress(button){
  button.classList.remove('cw-home-pressed');
  void button.offsetWidth;
  button.classList.add('cw-home-pressed');
  setTimeout(()=>button.classList.remove('cw-home-pressed'),170);
}
function handleHomeHit(hit,button){
  homePress(button);
  const map={
    coins:['Coins','Your coin balance'],
    gems:['Gems','Your gem balance'],
    bank:['Bank','Bank selected'],
    pass:['Free Pass','Season progress selected'],
    settings:['Settings','Settings selected'],
    chat:['Chat','Chat selected'],
    classic:['Classic Mode','Classic Mode selected'],
    wild:['Go Wild','Go Wild selected'],
    fun:['Fun Pack','Fun Pack selected'],
    contest:['Contest','Contest selected'],
    friendsplay:['Play With Friends','Friends mode selected'],
    bottomsettings:['Settings','Settings selected'],
    friends:['Friends','Friends selected'],
    league:['League','League selected'],
    events:['Events','Events selected'],
    canvas:['Canvas','Canvas selected'],
    sale:['Sale','Sale selected'],
    rewards:['Free Rewards Store','Rewards selected']
  };
  if(hit==='profile'){openProfile();return;}
  const msg=map[hit]||[hit,'Selected'];
  homeFeedback(msg[0],msg[1]);
}
(function wireCompleteHomeHitLayer(){
  const wire=()=>document.querySelectorAll('#finalDashboard .v37-hotspots [data-home-hit]').forEach(button=>{
    if(button.dataset.homeWired==='1')return;
    button.dataset.homeWired='1';
    const act=e=>{e.preventDefault();e.stopPropagation();handleHomeHit(button.dataset.homeHit,button)};
    button.addEventListener('click',act,{capture:false});
    button.addEventListener('pointerup',e=>{if(e.pointerType!=='mouse'){e.preventDefault();e.stopPropagation();}}, {passive:false});
    button.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();handleHomeHit(button.dataset.homeHit,button);}});
  });
  wire();
  window.setTimeout(wire,0);
  window.setTimeout(wire,250);
})();

// Keep the old hotspot bridge harmless for older cached markup. It never routes
// home options away from the home screen; Profile is the only exception.
function handleHomeHotspot(target){
  if(target==='profileBtn'){openProfile();return;}
  homeFeedback(String(target||'Option').replace(/([A-Z])/g,' $1').trim(),'Selected');
}

