// V40 — Profile: every visible control in the screenshot gets a real interaction.
(function wireFullProfileInteraction(){
  const layer=document.querySelector('#profile .profile-hit-layer');
  if(!layer || layer.dataset.wired==='1') return;
  layer.dataset.wired='1';

  function toast(title){
    const root=document.getElementById('profile');
    if(!root) return;
    let t=root.querySelector('.profile-hit-toast');
    if(!t){t=document.createElement('div');t.className='profile-hit-toast';root.appendChild(t)}
    t.textContent=title;
    t.classList.remove('show'); void t.offsetWidth; t.classList.add('show');
    clearTimeout(window.__profileHitToastTimer);
    window.__profileHitToastTimer=setTimeout(()=>t.classList.remove('show'),1200);
  }
  function press(b){
    b.classList.remove('profile-hit-pressed'); void b.offsetWidth; b.classList.add('profile-hit-pressed');
    setTimeout(()=>b.classList.remove('profile-hit-pressed'),170);
  }
  function personalize(){
    editingAvatar=avatarData();
    showProfileView('personalize');
    renderProfileAvatars();
    renderStyleTab('avatars');
  }
  function activate(key){
    if(['basic','medals','collections','recordings'].includes(key)){
      showProfileView(key);
      return;
    }
    if(['info','personalize','chatter','achievements','bag','mail'].includes(key)){
      if(key==='info') showProfileView('basic');
      else if(key==='personalize') personalize();
      else showProfileView(key);
      return;
    }
    const detailMap={
      trophies:['achievements','Max Trophies'],
      medalStat:['medals','Medals'],
      achievementStat:['achievements','Achievements']
    };
    if(detailMap[key]){showProfileView(detailMap[key][0]);toast(detailMap[key][1]);return;}
    const labels={
      coinPlus:'Coin balance selected',gemPlus:'Gem balance selected',name:'Profile name selected',
      club:'Club selected',level:'Level progress selected',vip:'VIP selected',share:'Share selected',
      glory:'Glory selected',data:'Data selected',currentLeague:'Current League selected',highestLeague:'Highest League selected',
      coinsWin:'Coins Win selected',biggestWin:'Biggest Coin Win selected',wins:'Total Wins selected',
      streak:'Best Win Streak selected',likes:'Likes selected',charisma:'Charisma selected'
    };
    if(key==='back'){show('finalDashboard');return;}
    if(key==='avatar'){personalize();return;}
    if(key==='edit'){document.getElementById('profileEditBtn')?.click();return;}
    if(key==='copy'){document.getElementById('profileCopyBtn')?.click();return;}
    if(key==='share'){document.getElementById('profileShareBtn')?.click();return;}
    toast(labels[key]||'Profile option selected');
  }
  layer.addEventListener('click',e=>{
    const b=e.target.closest('[data-profile-hit]');
    if(!b)return;
    e.preventDefault();e.stopPropagation();
    press(b);activate(b.dataset.profileHit);
  });
  layer.addEventListener('keydown',e=>{
    const b=e.target.closest('[data-profile-hit]');
    if(!b || (e.key!=='Enter' && e.key!==' '))return;
    e.preventDefault();press(b);activate(b.dataset.profileHit);
  });
})();
